package in.asr.ambulance;
import org.json.*;
public final class EnrollmentAndAlertsTest {
  static int count;static void yes(boolean value,String why){count++;if(!value)throw new AssertionError(why);}
  static JSONObject object(Object... values)throws Exception{JSONObject o=new JSONObject();for(int i=0;i<values.length;i+=2)o.put((String)values[i],values[i+1]);return o;}
  public static void main(String[] args)throws Exception{
    String origin="https://mapa.test",secret=new String(new char[64]).replace('\0','a');long now=1000000;
    JSONObject connection=object("origin",origin,"connect_token",secret,"status","pending","connect_expires_at",now+600000);
    yes(EnrollmentState.token(secret),"64 hex opaque connection");yes(!EnrollmentState.token("password"),"password is not connect credential");yes(EnrollmentState.belongs(connection,origin),"restored origin bound");yes(!EnrollmentState.belongs(connection,"https://other.test"),"other server rejected");yes(!EnrollmentState.renewable(connection,now),"pending not crew session");connection.put("status","approved");yes(EnrollmentState.renewable(connection,now),"approved renewable");yes(!EnrollmentState.renewable(connection,now+700000),"expiredconnection closed");
    yes(EnrollmentState.fresh(now-30000,now,20,false),"fresh actual GPS");yes(!EnrollmentState.fresh(now-120001,now,20,false),"old rejected");yes(!EnrollmentState.fresh(now+1,now,20,false),"future rejected");yes(!EnrollmentState.fresh(now,now,20,true),"mock rejected");yes(!EnrollmentState.fresh(now,now,101,false),"inaccurate rejected");yes(!EnrollmentState.validCoordinates(0,0),"placeholder location rejected");yes(!EnrollmentState.validCoordinates(Double.NaN,80),"nan rejected");
    JSONObject retry=object("status","unsent","payload",object("name","Actual crew"),"rejection_status",422);yes(EnrollmentState.recaptureAllowed(retry),"definite neveraccepted422 canrecapture");yes(!EnrollmentState.recaptureAllowed(new JSONObject(retry.toString()).put("rejection_status",0)),"uncertainbodycannotbediscarded");yes(!EnrollmentState.recaptureAllowed(new JSONObject(retry.toString()).put("rejection_status",429)),"rate limitedbodykept");yes(!EnrollmentState.recaptureAllowed(new JSONObject(retry.toString()).put("rejection_status",409)),"existingaccountconflictneedcontrol");yes(!EnrollmentState.recaptureAllowed(new JSONObject(retry.toString()).put("enrollment_id","accepted-A")),"acceptedregistrationcannotbe replaced");yes(!EnrollmentState.recaptureAllowed(new JSONObject(retry.toString()).put("status","approved")),"approvedregistrationcannotbe replaced");
    String immutable=retry.getJSONObject("payload").toString();yes(!EnrollmentState.submissionAllowed(retry),"definite422 cannot POST again before explicit recapture");yes(!EnrollmentState.automaticCheckAllowed(retry),"definite422 stops automatic poll");JSONObject conflict=new JSONObject(retry.toString()).put("rejection_status",409);yes(!EnrollmentState.submissionAllowed(conflict),"definite409 cannot POST again");yes(!EnrollmentState.automaticCheckAllowed(conflict),"definite409 stops automatic poll");JSONObject uncertain=new JSONObject(retry.toString());uncertain.remove("rejection_status");yes(EnrollmentState.submissionAllowed(uncertain),"uncertain original body may replay");yes(EnrollmentState.automaticCheckAllowed(uncertain),"uncertain registration continues bounded foreground retry");yes(EnrollmentState.submissionAllowed(new JSONObject(retry.toString()).put("rejection_status",429)),"a throttled uncertain action is retained for later retry");yes(retry.optInt("rejection_status")==422&&immutable.equals(retry.getJSONObject("payload").toString()),"poll policy preserves definite rejection and immutable body");yes(EnrollmentState.automaticCheckAllowed(object("status","pending")),"pending receipt still polls approval");yes(EnrollmentState.automaticCheckAllowed(object("status","approved")),"approved receipt can reconnect");for(String ended:new String[]{"rejected","revoked","cancelled"})yes(!EnrollmentState.automaticCheckAllowed(object("status",ended)),"terminal receipt stops automatic poll: "+ended);
    JSONObject duplicate=object("status","unsent","payload",object("name","Actual crew","email","crew@example.test"),"rejection_status",409,"rejection_message","This email already has an account or pending registration. Contact control; existing credentials are preserved.");
    String beforeRecovery=duplicate.toString();yes(EnrollmentState.existingLoginAllowed(duplicate),"definitive duplicate email may explicitly edit or return to password login");
    for(String status:new String[]{"pending","approved","rejected","revoked","cancelled"})yes(!EnrollmentState.existingLoginAllowed(new JSONObject(duplicate.toString()).put("status",status)),"receipt status never discarded for login: "+status);
    yes(!EnrollmentState.existingLoginAllowed(new JSONObject(duplicate.toString()).put("enrollment_id","accepted-A")),"server receipt prevents recovery discard");
    for(int status:new int[]{0,401,422,429,500})yes(!EnrollmentState.existingLoginAllowed(new JSONObject(duplicate.toString()).put("rejection_status",status)),"uncertain or different rejection preserved: "+status);
    for(String message:new String[]{"Registration action was already used with different details.","This phone connection was already submitted.",""})yes(!EnrollmentState.existingLoginAllowed(new JSONObject(duplicate.toString()).put("rejection_message",message)),"other conflicts preserve saved connection");
    JSONObject noPayload=new JSONObject(duplicate.toString());noPayload.remove("payload");yes(!EnrollmentState.existingLoginAllowed(noPayload),"only locally rejected payload can be discarded");yes(beforeRecovery.equals(duplicate.toString()),"recovery policy does not mutate registration evidence");
    JSONObject user=object("id","user_A","company_id","company_A","driver_id","driver_A","vehicle_id","vehicle_A","role","crew");JSONObject order=object("id","order_A","revision","rev1","can_acknowledge",true,"acknowledged",false);JSONObject snapshot=object("user",user,"capabilities",object("orders",true,"acknowledge",true),"orders",new JSONArray().put(order));
    JSONArray checked=new JSONArray();yes(NativeAlertPolicy.unchecked(snapshot,checked).length()==1,"new assignment alerts");checked=NativeAlertPolicy.checked(checked,NativeAlertPolicy.marker(snapshot,order));yes(NativeAlertPolicy.unchecked(snapshot,checked).length()==0,"checked stops without ACK");yes(!order.optBoolean("acknowledged"),"checking never accepts");JSONArray restored=new JSONArray(checked.toString());yes(NativeAlertPolicy.unchecked(snapshot,restored).length()==0,"process restart retains checkedrevision");order.put("revision","rev2");yes(NativeAlertPolicy.unchecked(snapshot,restored).length()==1,"new call revision alerts again");user.put("driver_id","driver_B");yes(NativeAlertPolicy.unchecked(snapshot,checked).length()==1,"reassignment marker scope changes");order.put("acknowledged",true);yes(NativeAlertPolicy.unchecked(snapshot,checked).length()==0,"accepted assignment no ring");
    yes(NativeAlertPolicy.audible(true,true,4,true,true,5),"normal audible");yes(!NativeAlertPolicy.audible(false,true,4,true,true,5),"blockednotifications silent");yes(!NativeAlertPolicy.audible(true,false,4,true,true,5),"silentchannel respected");yes(!NativeAlertPolicy.audible(true,true,2,true,true,5),"lowchannel respected");yes(!NativeAlertPolicy.audible(true,true,4,false,true,5),"silent/vibrate respected");yes(!NativeAlertPolicy.audible(true,true,4,true,false,5),"DND respected");yes(!NativeAlertPolicy.audible(true,true,4,true,true,0),"volumezero respected");
    yes(NativeAlertPolicy.localTestAllowed(0,true),"local test allowed only with visible activity");yes(!NativeAlertPolicy.localTestAllowed(1,true),"local test cannot replace real assignment ring");yes(!NativeAlertPolicy.localTestAllowed(0,false),"local test stops in background");
    System.out.println("Enrollment / alert behavior assertions: "+count);
  }
}
